	{"disable-mouse", 0, "bool", "--disable-mouse"},
	{"exec", 'e', "bool", "-e, --exec"},
	{"exit-write", 'X', "bool", "-X, --exit-write"},
	{"exit-write-after", 'a', "int", "-a, --exit-write-after"},
	{"exit-write-before", 'b', "int", "-b, --exit-write-before"},
	{"filter", 0, "string", "--filter"},
	{"follow-all", 'A', "bool", "-A, --follow-all"},
	{"follow-mode", 'f', "bool", "-f, --follow-mode"},
	{"follow-name", 0, "bool", "--follow-name"},
	{"follow-section", 0, "bool", "--follow-section"},
	{"force-screen", 0, "bool", "--force-screen"},
	{"header", 'H', "int", "-H, --header"},
	{"header-column", 'Y', "int", "-Y, --header-column"},
	{"help", 'h', "bool", "-h, --help"},
	{"help-key", 0, "bool", "--help-key"},
	{"hide-other-section", 0, "bool", "--hide-other-section"},
	{"hscroll-width", 0, "string", "--hscroll-width"},
	{"incsearch", 0, "boolopt", "--incsearch"},
	{"jump-target", 'j', "string", "-j, --jump-target"},
